import math
from typing import List, Tuple

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def find_gcd_matrix(r: int, c: int) -> Tuple[List[List[int]], int]:
    if r == 1 and c == 1:
        return ([[0]], 0)

    # Try to find a diverse matrix with a reasonable upper bound
    upper_bound = 10**9
    for a in range(1, upper_bound + 1):
        for b in range(1, upper_bound + 1):
            for c in range(1, upper_bound + 1):
                for d in range(1, upper_bound + 1):
                    if gcd(a, b) != gcd(c, d) and gcd(a, c) != gcd(b, d) and gcd(a, d) != gcd(b, c):
                        matrix = [[a, b], [c, d]]
                        if len(set([gcd(row) for row in matrix]) | set([gcd(col) for col in zip(*matrix)])) == r + c:
                            return (matrix, max(gcd(row) for row in matrix))
    return ([[0]], 0)

def main():
    r, c = map(int, input().split())
    matrix, magnitude = find_gcd_matrix(r, c)
    if magnitude == 0:
        print(0)
    else:
        for row in matrix:
            print(' '.join(map(str, row)))

if __name__ == "__main__":
    main()
